import{_ as n,a0 as a,w as r,s as g,ao as p,I as t,a1 as l,A as s,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Kali Linux 中安裝 Google Chrome 瀏覽器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kali Linux 中安裝 Google Chrome 瀏覽器 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kali Linux 中安裝 Google Chrome 瀏覽器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kali Linux 中安裝 Google Chrome 瀏覽器 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170121 How to install Google Chrome Browser on Kali Linux","title":"如何在 Kali Linux 中安裝 Google Chrome 瀏覽器","tag":"201702","desc":""},"relativePath":"201702/20170121 How to install Google Chrome Browser on Kali Linux.md","filePath":"[post].md"}'),d={name:"201702/20170121 How to install Google Chrome Browser on Kali Linux.md"};function h(u,e,m,c,b,k){const i=a("Link");return r(),g("div",null,[e[15]||(e[15]=p(`<h1 id="如何在-kali-linux-中安裝-google-chrome-瀏覽器" tabindex="-1">如何在 Kali Linux 中安裝 Google Chrome 瀏覽器 <a class="header-anchor" href="#如何在-kali-linux-中安裝-google-chrome-瀏覽器" aria-label="Permalink to “如何在 Kali Linux 中安裝 Google Chrome 瀏覽器”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p><strong>目的</strong></p><p>我們的目標就是在 Kali Linux 上安裝好 Google Chrome Web 瀏覽器。同時，請參閲附錄為可能出現的問題進行排查。</p><p><strong>要求</strong></p><p>需要獲得已安裝 Kali Linux 或者 Live 系統的特權。</p><p><strong>困難程度</strong></p><p>容易。</p><p><strong>慣例</strong></p><ul><li><code>#</code> - 給定命令需要以 root 用户權限運行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 給定命令以常規權限用户運行</li></ul><h3 id="步驟説明" tabindex="-1">步驟説明 <a class="header-anchor" href="#步驟説明" aria-label="Permalink to “步驟説明”">​</a></h3><p><strong>下載 Google Chrome</strong></p><p>首先，使用 <code>wget</code> 命令來下載最新版本的 Google Chrome 的 debian 安裝包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wget https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p><strong>安裝 Google Chrome</strong></p><p>在 Kali Linux 安裝 Google Chrome 最容易的方法就是使用 <code>gdebi</code>，它會自動幫你下載所有的依賴包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># gdebi google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p><strong>啓動 Google Chrome</strong></p><p>開啓一個終端（terminal），執行 <code>google-chrome</code> 命令來啓動 Google Chrome 瀏覽器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ google-chrome</span></span></code></pre></div><h3 id="附錄" tabindex="-1">附錄 <a class="header-anchor" href="#附錄" aria-label="Permalink to “附錄”">​</a></h3><p><strong>非法指令 (Illegal Instruction)</strong></p><p>當以 root 用户特權來運行 <code>google-chrome</code> 命令是，會出現 非法指令 (Illegal Instruction) 錯誤信息。因為通常情況下，Kali Linux 默認情況下的默認用户是 root 用户，我們需要創建一個虛的非特權用户，比如 <code>linuxconfig</code>，然後使用這個用户來啓動 Google Chrome 瀏覽器。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -m -d /home/linuxconfig linuxconfig</span></span>
<span class="line"><span># su linuxconfig -c google-chrome</span></span></code></pre></div><p><strong>libappindicator1 包未安裝</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg: dependency problems prevent configuration of google-chrome-stable:</span></span>
<span class="line"><span> google-chrome-stable depends on libappindicator1; however:</span></span>
<span class="line"><span>  Package libappindicator1 is not installed.</span></span></code></pre></div><p>使用 <code>gdebi</code> 命令來安裝 Google Chrome 的 debian 包可以解決依賴問題。參閲上文。</p><p><img src="https://linuxconfig.org/images/kali-linux-google-chome-browser-start.jpg" alt="在 Kali Linux 中以普通用户啓動 google chrome"></p><hr><p>譯者簡介：</p>`,30)),t("p",null,[l(i,{href:"http://GHLandy.com"},{default:s(()=>[...e[0]||(e[0]=[o("GHLandy",-1)])]),_:1}),e[1]||(e[1]=o(" —— 生活中所有歡樂與苦悶都應藏在心中，有些事兒註定無人知曉，自己也無從説起。",-1))]),e[16]||(e[16]=t("hr",null,null,-1)),t("p",null,[e[3]||(e[3]=o("via: ",-1)),l(i,{href:"https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux"},{default:s(()=>[...e[2]||(e[2]=[o("https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=o("作者：",-1)),l(i,{href:"https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux"},{default:s(()=>[...e[4]||(e[4]=[o("Lubos Rendek",-1)])]),_:1}),e[8]||(e[8]=o(" 譯者：",-1)),l(i,{href:"https://github.com/GHLandy"},{default:s(()=>[...e[5]||(e[5]=[o("GHLandy",-1)])]),_:1}),e[9]||(e[9]=o(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...e[6]||(e[6]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=o("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[o("Linux中國",-1)])]),_:1}),e[14]||(e[14]=o(" 榮譽推出",-1))])])}const L=n(d,[["render",h]]);export{C as __pageData,L as default};
